import React, { useEffect, useState, useCallback } from "react";
import { normalizePokemonName } from "./normalizePokemon";

const getMovesetPath = (battleMode) =>
    battleMode === "singles"
        ? "/singles/csv_movesets/"
        : "/doubles/csv_movesets/";

// 🔥 GLOBAL MOVE CACHE
let moveDataMap = {};

export default function PokemonBuildPanel({
    clickedBuild,
    battleMode,
}) {
    const [buildData, setBuildData] = useState(null);
    const [imgSrc, setImgSrc] = useState(null);
    const [tooltip, setTooltip] = useState(null);
    const [cache, setCache] = useState({});

    const MOVESET_PATH = getMovesetPath(battleMode);

    const normalize = (name) =>
        name
            ?.toLowerCase()
            .replace(/[^a-z0-9\s-]/g, "")
            .trim()
            .replace(/\s+/g, "-");

    const resolveImage = useCallback((name) => {
        return `/pokemon_artwork/${normalize(name)}.jpg`;
    }, []);

    const handleImgError = (e, name) => {
        const base = `/pokemon_artwork/${normalize(name)}`;
        if (e.target.src.endsWith(".jpg")) {
            e.target.src = `${base}.png`;
        } else {
            e.target.style.display = "none";
        }
    };

    const loadCSV = async (path) => {
        const res = await fetch(path);
        return await res.text();
    };

    const parseCSV = (text) =>
        text
            .trim()
            .split(/\r?\n/)
            .slice(1)
            .map((r) =>
                r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
            );

    // 🔥 LOAD MOVE STATS CSV ONCE
    useEffect(() => {
        const loadMoveCSV = async () => {
            const res = await fetch("/Move_Stats.csv");
            const text = await res.text();

            const rows = text
                .trim()
                .split(/\r?\n/)
                .slice(1)
                .map(r => r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/));

            const map = {};

            rows.forEach(row => {
                const name = row[1]?.toLowerCase();
                if (!name) return;

                map[name] = {
                    type: row[2],
                    category: row[3],
                    effect: (row[8] || "").replace(/\?/g, "good attack for damage"),
                };
            });

            moveDataMap = map;
        };

        loadMoveCSV();
    }, []);

    // 🎨 TYPE COLORS
    const typeColors = {
        fire: "#F08030",
        water: "#6890F0",
        grass: "#78C850",
        electric: "#F8D030",
        ice: "#98D8D8",
        fighting: "#C03028",
        poison: "#A040A0",
        ground: "#E0C068",
        flying: "#A890F0",
        psychic: "#F85888",
        bug: "#A8B820",
        rock: "#B8A038",
        ghost: "#705898",
        dragon: "#7038F8",
        dark: "#705848",
        steel: "#B8B8D0",
        fairy: "#EE99AC",
        normal: "#A8A878",
    };

    // ⚔️ CATEGORY ICONS
    const getCategoryIcon = (category) => {
        if (category === "Physical") return "⚔️";
        if (category === "Special") return "✨";
        if (category === "Status") return "🛠️";
        return "";
    };

    // 🔥 FETCH INFO
    const fetchInfo = async (name, category) => {
        const key = `${category}-${name}`;
        if (cache[key]) return cache[key];

        const formatted = normalize(name);

        let info = "";

        // ✅ USE LOCAL CSV FOR MOVES
        if (category === "Moves") {
            const move = moveDataMap[formatted];
            if (move) {
                info = move.effect || "No effect data";
            }
        }

        // 🔁 FALLBACK (abilities/items/stats)
        if (!info && category !== "Moves") {
            let pokeapiUrl = "";
            let mcpEndpoint = "";

            if (category === "Abilities") {
                pokeapiUrl = `https://pokeapi.co/api/v2/ability/${formatted}`;
                mcpEndpoint = `http://localhost:3000/pokemon_get_ability?name=${formatted}`;
            }
            else if (category === "Items") {
                pokeapiUrl = `https://pokeapi.co/api/v2/item/${formatted}`;
                mcpEndpoint = `http://localhost:3000/pokemon_get_item?name=${formatted}`;
            }
            else if (category === "Stats") {
                pokeapiUrl = `https://pokeapi.co/api/v2/nature/${formatted}`;
            }

            try {
                const res = await fetch(pokeapiUrl);
                const data = await res.json();

                if (category === "Abilities" || category === "Items") {
                    const entry = data.effect_entries?.find(
                        (e) => e.language.name === "en"
                    );
                    info = entry?.short_effect || entry?.effect;
                }

                else if (category === "Stats") {
                    const formatStat = (s) =>
                        s?.name
                            ?.replace("special-attack", "SP. ATK")
                            .replace("special-defense", "SP. DEF")
                            .replace("-", " ")
                            .toUpperCase();

                    if (data.increased_stat && data.decreased_stat) {
                        info = `Boosts ${formatStat(
                            data.increased_stat
                        )}, lowers ${formatStat(
                            data.decreased_stat
                        )}`;
                    } else {
                        info = "No stat changes";
                    }
                }
            } catch {
                info = "";
            }

            if (!info && mcpEndpoint) {
                try {
                    const res = await fetch(mcpEndpoint);
                    const data = await res.json();

                    info =
                        data?.effect ||
                        data?.description ||
                        data?.short_effect;
                } catch {
                    info = "No data found";
                }
            }
        }

        if (!info) info = name;

        const cleaned = info.replace(/\n|\f/g, " ");

        setCache((prev) => ({
            ...prev,
            [key]: cleaned,
        }));

        return cleaned;
    };

    useEffect(() => {
        if (!clickedBuild || !clickedBuild.sourceFile) {
            setBuildData(null);
            return;
        }

        const loadBuild = async () => {
            const text = await loadCSV(
                MOVESET_PATH + clickedBuild.sourceFile
            );

            const rows = parseCSV(text);

            const pokemonRows = rows.filter(
                (r) =>
                    normalizePokemonName(r[1]) ===
                    normalizePokemonName(clickedBuild.pokemon)
            );

            const grouped = {};

            for (let row of pokemonRows) {
                const category = row[2];

                if (category === "Spreads") continue;

                const itemName =
                    category === "Stats"
                        ? row[3]
                        : row[4];

                const usage = row[5];

                if (
                    category === "Stats" &&
                    ["Raw count", "Viability Ceiling", "Avg. weight"].includes(itemName)
                ) continue;

                if (!itemName) continue;

                if (!grouped[category]) {
                    grouped[category] = [];
                }

                grouped[category].push({
                    name: itemName,
                    usage,
                });
            }

            Object.keys(grouped).forEach((cat) => {
                grouped[cat] = grouped[cat]
                    .sort((a, b) => Number(b.usage) - Number(a.usage))
                    .slice(0, 5);
            });

            setImgSrc(resolveImage(clickedBuild.display));

            setBuildData({
                display: clickedBuild.display,
                month: clickedBuild.month,
                data: grouped,
            });
        };

        loadBuild();
    }, [clickedBuild, MOVESET_PATH, resolveImage]);

    if (!buildData) {
        return <div style={{ padding: "10px" }}>Click a graph point to view build</div>;
    }

    return (
        <div style={{
            width: "350px",
            height: "600px",
            overflowY: "auto",
            border: "1px solid #ccc",
            borderRadius: "10px",
            padding: "12px",
            background: "#fafafa",
            position: "relative",
        }}>
            <img
                src={imgSrc}
                alt={buildData.display}
                onError={(e) => handleImgError(e, buildData.display)}
                style={{ width: "110px", display: "block", margin: "0 auto 10px" }}
            />

            <h3 style={{ textAlign: "center" }}>
                {buildData.display} — {buildData.month}
            </h3>

            {Object.entries(buildData.data).map(([category, items]) => (
                <div key={category} style={{ marginBottom: "12px" }}>
                    <strong>{category === "Stats" ? "Natures" : category}</strong>

                    <ul style={{ marginTop: "5px", paddingLeft: "18px" }}>
                        {items.map((item, idx) => {
                            const move = moveDataMap[normalize(item.name)];
                            const color =
                                category === "Moves" && move
                                    ? typeColors[move.type?.toLowerCase()] || "#ccc"
                                    : "#000";

                            const icon =
                                category === "Moves" && move
                                    ? getCategoryIcon(move.category)
                                    : "";

                            return (
                                <li
                                    key={idx}
                                    onMouseEnter={async (e) => {
                                        setTooltip({
                                            text: "Loading...",
                                            x: e.clientX,
                                            y: e.clientY,
                                        });

                                        const info = await fetchInfo(item.name, category);

                                        setTooltip({
                                            text: info,
                                            x: e.clientX,
                                            y: e.clientY,
                                        });
                                    }}
                                    onMouseLeave={() => setTooltip(null)}
                                    style={{
                                        cursor: "pointer",
                                        marginBottom: "3px",
                                        color,
                                        fontWeight: category === "Moves" ? "bold" : "normal",
                                    }}
                                >
                                    {item.name} {icon} ({item.usage}%)
                                </li>
                            );
                        })}
                    </ul>
                </div>
            ))}

            {tooltip && (
                <div style={{
                    position: "fixed",
                    top: tooltip.y + 10,
                    left: tooltip.x + 10,
                    background: "#222",
                    color: "#fff",
                    padding: "8px",
                    borderRadius: "6px",
                    maxWidth: "300px",
                    fontSize: "12px",
                    zIndex: 9999,
                }}>
                    {tooltip.text}
                </div>
            )}
        </div>
    );
}
